const e=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const modes={card:'フラッシュカード',read:'英語 → 意味',listen:'音声 → 意味',recall:'意味 → 英語',match:'組み合わせ'};
export function renderFastSetup({app,cards,state,mutate},startFast,mode){
 const pref=state.fastPreferences||{},themes=[...new Set(cards.map(c=>c.theme))],filters=pref.filters||['new'],selected=pref.themes||[],f=state.fast;
 app.innerHTML=`<div class="narrow"><a href="#home">← ホーム</a><div class="eyebrow">FLASHCARDS · WORD & MEANING</div><h1>ことばと意味</h1><p>単語カードの表は英語、裏は意味。めくって、思い出して、確かめよう。</p><section class="panel"><form id="fast-setup"><fieldset><legend>① 対象（いくつでも）</legend><div class="choice-checks">${Object.entries({all:'すべて',new:'これから覚える',weak:'もう一度たしかめたい',due:'復習の時期'}).map(([k,v])=>`<label><input name="filter" type="checkbox" value="${k}" ${filters.includes(k)?'checked':''}>${v}</label>`).join('')}</div></fieldset><fieldset><legend>② テーマ（いくつでも）</legend><div class="actions"><button type="button" id="themes-all">すべて選ぶ</button><button type="button" id="themes-none">選び直す</button></div><div class="choice-checks">${themes.map(t=>`<label><input name="theme" type="checkbox" value="${e(t)}" ${!selected.length||selected.includes(t)?'checked':''}>${e(t)}</label>`).join('')}</div></fieldset><fieldset><legend>③ 進み方</legend><div class="choice-checks">${Object.entries(modes).map(([k,v])=>`<label><input name="mode" type="radio" value="${k}" ${(mode||pref.mode||'card')===k?'checked':''}>${v}</label>`).join('')}</div><div class="choice-checks">${Object.entries({random:'ランダム',importance:'参考重要度順',alphabetical:'ABC順',original:'収録順'}).map(([k,v])=>`<label><input name="order" type="radio" value="${k}" ${(pref.order||'random')===k?'checked':''}>${v}</label>`).join('')}</div><label><input name="auto" type="checkbox" ${pref.auto?'checked':''}> 自力正解したら自動で次へ</label><p class="muted">並び順はフラッシュカード用。確認問題の順番と選択肢はランダムです。長期定着済みは「すべて」で練習できます。</p></fieldset><p id="setup-count" role="status"></p><button class="primary" type="submit">この設定ではじめる →</button></form>${f&&f.index<f.ids.length?'<button id="fast-resume">前のつづきから →</button>':''}<p><a href="#goal">目標日から、今日のおすすめを自動で決める →</a></p></section></div>`;
 const form=app.querySelector('form'),values=name=>[...form.querySelectorAll(`[name="${name}"]:checked`)].map(el=>el.value),count=()=>{const n=values('theme').length,ok=n&&values('filter').length;app.querySelector('#setup-count').textContent=ok?n+'テーマを選択中':'対象とテーマをそれぞれ1つ以上選んでね';form.querySelector('[type=submit]').disabled=!ok;};form.onchange=count;
 for(const [id,checked] of [['#themes-all',true],['#themes-none',false]])app.querySelector(id).onclick=()=>{form.querySelectorAll('[name=theme]').forEach(el=>el.checked=checked);count();};
 form.onsubmit=async ev=>{ev.preventDefault();if(!values('theme').length||!values('filter').length)return;const p={themes:values('theme'),filters:values('filter'),mode:values('mode')[0],order:values('order')[0],auto:!!form.querySelector('[name=auto]').checked};await mutate(s=>{s.fastPreferences=p;startFast(s,cards,p.mode,p.filters,p.themes,p.order);s.fast.auto=p.auto;});location.hash='fast';};
 const resume=app.querySelector('#fast-resume');if(resume)resume.onclick=()=>{location.hash='fast';};count();
}
